#!/usr/bin/env python3
"""Record bytes actually generated by this run, separately from immutable sources."""
import hashlib,json
from pathlib import Path
root=Path(__file__).resolve().parents[1]
outputs={p.relative_to(root).as_posix():hashlib.sha256(p.read_bytes()).hexdigest()
    for p in sorted((root/'results').iterdir()) if p.is_file()}
needed={'results/report.json','results/differential_kernel_invariance_ledger.csv',
        'results/parent_q_transport_comparison.csv','results/kernel_source_competition.png',
        'results/kernel_projector_rate_balance.png','results/temporal_derivative_stability.png'}
if not needed.issubset(outputs):raise RuntimeError('Missing mandatory outputs: '+str(needed-set(outputs)))
(root/'SHA256SUMS_OUTPUT.json').write_text(json.dumps({'root':root.name,'file_sha256':outputs},indent=2)+'\n')
print('v18.50r OUTPUT MANIFEST WRITTEN',len(outputs))
